<?php declare(strict_types=1);require_once __DIR__.'/includes/functions.php';$error='';if(post()){verifyCsrf();$name=clean('full_name',150);$email=emailField('email');$phone=clean('phone',40);$age=(int)($_POST['age']??0);$area=clean('area',120);$availability=clean('availability',120);$mot=clean('motivation',5000);if(!$name||!$email||!$phone||$age<13||!$area||!$availability||mb_strlen($mot)<20)$error='Please complete the application with valid information.';else{db()->prepare('INSERT INTO volunteer_applications(full_name,email,phone,age,area_of_interest,availability,motivation) VALUES(?,?,?,?,?,?,?)')->execute([$name,$email,$phone,$age,$area,$availability,$mot]);flash('success','Volunteer application submitted.');redirect('volunteer.php');}}$pageTitle='Volunteer';require __DIR__.'/includes/header.php';?><div class="form-shell"><p class="eyebrow">Get involved</p><h1>Volunteer with ATACJL.</h1><?php if($error):?><div class="flash error" style="position:static"><?=e($error)?></div><?php endif;?><form method="post"><?=csrfField()?><div class="field"><label>Full name</label><input name="full_name" required></div><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Phone</label><input name="phone" required></div><div class="field"><label>Age</label><input type="number" min="13" max="100" name="age" required></div><div class="field"><label>Area of interest</label><input name="area" placeholder="Culture, youth, sport..." required></div><div class="field"><label>Availability</label><input name="availability" placeholder="Weekends, evenings..." required></div><div class="field"><label>Motivation</label><textarea name="motivation" required></textarea></div><button class="btn coral">Apply to volunteer</button></form></div><?php require __DIR__.'/includes/footer.php';
